package com.bank.balance;

import java.util.*;
import java.util.logging.*;

public class RunningSumDemo {
    private static final Logger log = Logger.getLogger("Balance");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> deposits = List.of(1000, 2000, 500, 1500);
        BalanceService service = new BalanceService();

        log.info(() -> "AtomicInteger : " + service.runningSumAtomic(deposits));
        log.info(() -> "parallelPrefix: " + service.runningSumPrefix(deposits));
    }
}

// ─── Would be in service/BalanceService.java ───
class BalanceService {
    // sequential-only accumulator (common interview answer)
    List<Integer> runningSumAtomic(List<Integer> amounts) {
        java.util.concurrent.atomic.AtomicInteger sum =
            new java.util.concurrent.atomic.AtomicInteger(0);
        return amounts.stream()
            .sequential()                       // MUST be sequential (shared state)
            .map(sum::addAndGet)                // running total
            .toList();
    }

    // preferred: Arrays.parallelPrefix (parallel-safe, no shared mutable state in stream)
    List<Integer> runningSumPrefix(List<Integer> amounts) {
        int[] arr = amounts.stream().mapToInt(Integer::intValue).toArray();
        java.util.Arrays.parallelPrefix(arr, Integer::sum);   // in-place prefix sums
        return java.util.stream.IntStream.of(arr).boxed().toList();
    }
}
